from pathlib import Path
import csv,json,math
BASE=Path(__file__).resolve().parent
def rows(n):
 p=BASE/n
 return list(csv.DictReader(p.open(encoding='utf-8'))) if p.exists() else []
def main():
 cp=rows('corrected_pilot_performance_summary_both_families.csv'); cf=rows('confirmatory_performance_summary_both_families.csv'); pair=rows('confirmatory_paired_outer_method_comparisons.csv'); led=rows('confirmatory_outer_dataset_run_ledger.csv'); indep=json.loads((BASE/'corrected_pilot_independent_comparison_records.json').read_text()) if (BASE/'corrected_pilot_independent_comparison_records.json').exists() else {}
 def find(sid,scale,ep,m,fam): return next((r for r in cf if r['scenario_id']==sid and r['scale_method']==scale and r['endpoint']==ep and r['method']==m and r['interval_family']==fam),None)
 highlights=[]
 for fam in ('percentile','basic'):
  p2=find('S1','MAD','rms_shape_displacement','P2_fixed_transform',fam); p3=find('S1','MAD','rms_shape_displacement','P3_joint_unstratified',fam)
  pr=next((r for r in pair if r['scenario_id']=='S1' and r['scale_method']=='MAD' and r['endpoint']=='rms_shape_displacement' and r['interval_family']==fam and r['method_a']=='P2_fixed_transform' and r['method_b']=='P3_joint_unstratified'),{})
  highlights.append({'question':'S1/MAD RMS shape','interval_family':fam,'P2_coverage':p2['coverage_available'] if p2 else None,'P2_coverage_N':p2['available_intervals'] if p2 else None,'P2_width':p2['mean_width_available'] if p2 else None,'P2_availability':p2['availability_rate'] if p2 else None,'P3_coverage':p3['coverage_available'] if p3 else None,'P3_coverage_N':p3['available_intervals'] if p3 else None,'P3_width':p3['mean_width_available'] if p3 else None,'P3_availability':p3['availability_rate'] if p3 else None,'paired_availability_diff':pr.get('availability_diff_mean'),'paired_availability_MCSE':pr.get('availability_diff_mcse'),'paired_covered_all_diff':pr.get('available_and_covered_diff_mean'),'paired_covered_all_MCSE':pr.get('available_and_covered_diff_mcse'),'paired_both_available_N':pr.get('both_available_n'),'paired_conditional_coverage_diff':pr.get('conditional_coverage_diff_mean'),'paired_conditional_coverage_MCSE':pr.get('conditional_coverage_diff_mcse'),'paired_width_diff':pr.get('paired_width_diff_mean'),'paired_width_MCSE':pr.get('paired_width_diff_mcse')})
  p2=find('S5','MAD','rms_shape_displacement','P2_fixed_transform',fam); p3=find('S5','MAD','rms_shape_displacement','P3_joint_unstratified',fam)
  pr=next((r for r in pair if r['scenario_id']=='S5' and r['scale_method']=='MAD' and r['endpoint']=='rms_shape_displacement' and r['interval_family']==fam and r['method_a']=='P2_fixed_transform' and r['method_b']=='P3_joint_unstratified'),{})
  highlights.append({'question':'S5/MAD RMS shape','interval_family':fam,'P2_coverage':p2['coverage_available'] if p2 else None,'P2_coverage_N':p2['available_intervals'] if p2 else None,'P2_width':p2['mean_width_available'] if p2 else None,'P2_availability':p2['availability_rate'] if p2 else None,'P2_available_and_covered':p2['available_and_covered_all'] if p2 else None,'P3_coverage':p3['coverage_available'] if p3 else None,'P3_coverage_N':p3['available_intervals'] if p3 else None,'P3_width':p3['mean_width_available'] if p3 else None,'P3_availability':p3['availability_rate'] if p3 else None,'P3_available_and_covered':p3['available_and_covered_all'] if p3 else None,'paired_availability_diff':pr.get('availability_diff_mean'),'paired_availability_MCSE':pr.get('availability_diff_mcse'),'paired_covered_all_diff':pr.get('available_and_covered_diff_mean'),'paired_covered_all_MCSE':pr.get('available_and_covered_diff_mcse'),'paired_both_available_N':pr.get('both_available_n'),'paired_conditional_coverage_diff':pr.get('conditional_coverage_diff_mean'),'paired_conditional_coverage_MCSE':pr.get('conditional_coverage_diff_mcse'),'paired_width_diff':pr.get('paired_width_diff_mean'),'paired_width_MCSE':pr.get('paired_width_diff_mcse')})
 with (BASE/'confirmatory_primary_questions.csv').open('w',encoding='utf-8',newline='') as f:
  fields=[]
  for row in highlights:
   for key in row:
    if key not in fields: fields.append(key)
  w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(highlights)
 n=len(led); verdict='CORRECTED PILOT AND CONFIRMATORY SIMULATION COMPLETE — EMPIRICAL ANALYSIS REQUIRES SEPARATE REVIEW' if n==4000 and indep.get('status')=='PASS' else 'SIMULATION MILESTONE INCOMPLETE — EXACT BLOCKERS AND RESUME STATE DOCUMENTED'
 text=f'''# Step 5B-B3 confirmatory simulation report\n\n## Final verdict\n\n**{verdict}**\n\nB2's 499-replicate interval gate was impossible (`floor(0.025*499)=12 < 20`), so B2 interval coverage is exploratory. The corrected replay uses 999 attempted draws, requires at least 950 valid draws, requires `floor(0.025*n_valid)>=20`, and separately persists every gate.\n\nCorrected pilot: six scenarios, 100 outer datasets per scenario, 999 bootstrap attempts, four procedures, two scales, three endpoints, and both interval families. Confirmatory run: S1 and S5, 2,000 outer datasets each, with the same corrected contract and disjoint streams. S2/S3/S4/S6 remain diagnostic corrected-pilot scenarios.\n\nThe primary questions and compact denominators are in `confirmatory_primary_questions.csv`. Paired comparisons are computed from outer-level differences with method-specific applicable N and SD/sqrt(N) MCSEs; marginal coverage subtraction is not used. Unavailable intervals reduce available-and-covered probability over all attempted datasets but are excluded from conditional coverage.\n\nNo result establishes clinical reliability, individual reportability, developmental validity, population norms, or empirical CHAVI inference.\n'''
 (BASE/'CONFIRMATORY_SIMULATION_REPORT.md').write_text(text,encoding='utf-8')
 claims=[['C1','B2 gate contradiction documented','B2','B2_CONTRACT_AND_OUTPUT_RECONCILIATION.md','PASS'],['C2','Corrected pilot complete with 999 draws','corrected_pilot','corrected_pilot_outer_dataset_run_ledger.csv','PASS' if len(rows('corrected_pilot_outer_dataset_run_ledger.csv'))==600 else 'FAIL'],['C3','Confirmatory S1/S5 complete with 2000 each','confirmatory','confirmatory_outer_dataset_run_ledger.csv','PASS' if n==4000 else 'PENDING'],['C4','Independent point/bootstrap/hash validation','all','corrected_pilot_independent_comparison_records.json','PASS' if indep.get('status')=='PASS' else 'FAIL'],['C5','No empirical CHAVI inference','all','README_REPRODUCE.md','PASS']]
 with (BASE/'scientific_claims_and_readiness_register.csv').open('w',encoding='utf-8',newline='') as f:
  w=csv.writer(f,lineterminator='\n');w.writerow(['claim_id','claim','stage','evidence','status']);w.writerows(claims)
 print(verdict)
if __name__=='__main__':main()
